(() => {
  const cfg = window.PORTFOLIO_CONFIG || {};
  const ready = !!(
    cfg &&
    cfg.SUPABASE_URL &&
    cfg.SUPABASE_ANON_KEY &&
    !String(cfg.SUPABASE_URL).includes('YOUR_') &&
    !String(cfg.SUPABASE_ANON_KEY).includes('YOUR_')
  );

  const isEn = () => document.documentElement.lang === 'en';
  const dict = (ar, en) => (isEn() ? en : ar);

  const showToast = (msg, type = 'info') => {
    if (typeof window.showPortfolioToast === 'function') {
      window.showPortfolioToast(msg, type);
      return;
    }
    let host = document.getElementById('toastHost');
    if (!host) {
      host = document.createElement('div');
      host.id = 'toastHost';
      host.className = 'toast-host';
      document.body.appendChild(host);
    }
    const item = document.createElement('div');
    item.className = 'toast-item ' + type;
    item.textContent = msg;
    host.appendChild(item);
    setTimeout(() => {
      item.style.opacity = '0';
      item.style.transform = 'translateY(8px)';
      setTimeout(() => item.remove(), 300);
    }, 3400);
  };

  const setStatus = (el, msg, state = '') => {
    if (!el) return;
    el.textContent = msg;
    el.dataset.state = state;
  };

  const invoke = async (name, body) => {
    if (!ready) {
      throw new Error(
        dict(
          'الخادم الخلفي غير متصل بعد. يلزم إعداد public/config.js ونشر وظائف Supabase أولًا.',
          'Backend service is not connected yet. Configure public/config.js and deploy Supabase Edge Functions first.'
        )
      );
    }
    const endpoint = String(cfg.SUPABASE_URL).replace(/\/$/, '') + '/functions/v1/' + name;
    const res = await fetch(endpoint, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        apikey: cfg.SUPABASE_ANON_KEY,
        Authorization: 'Bearer ' + cfg.SUPABASE_ANON_KEY
      },
      body: JSON.stringify(body)
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) {
      throw new Error(
        data.error || dict('تعذر إكمال الطلب حاليًا. حاول لاحقًا.', 'Request failed. Please try again later.')
      );
    }
    return data;
  };

    const MASCOT_SPRITES = {"wave": "data:image/webp;base64,", "excited": "data:image/webp;base64,", "idle": "data:image/webp;base64,", "thinking": "data:image/webp;base64,", "greet": "data:image/webp;base64,"};
  let setMascotMood = () => {};

  // 0A. Legendary Cinema Entry & Anime Welcome Gate (#legendaryEntryGate)
  try {
    const prefersReduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (!prefersReduced && !document.getElementById('legendaryEntryGate')) {
      const entryStyle = document.createElement('style');
      entryStyle.id = 'legendaryEntryGateStyles';
      entryStyle.textContent = `
        #legendaryEntryGate {
          position: fixed;
          inset: 0;
          z-index: 999999;
          display: grid;
          place-items: center;
          padding: 18px;
          background:
            radial-gradient(circle at 20% 20%, rgba(201, 242, 122, 0.16), transparent 45%),
            radial-gradient(circle at 82% 78%, rgba(74, 222, 222, 0.14), transparent 48%),
            radial-gradient(circle at 50% 45%, rgba(213, 197, 164, 0.12), #070807 76%);
          color: #eeeae0;
          overflow-y: auto;
          transition: opacity 0.75s cubic-bezier(.2,.75,.2,1), transform 0.75s cubic-bezier(.2,.75,.2,1), visibility 0.75s;
        }
        #legendaryEntryGate.is-entering {
          opacity: 0;
          transform: scale(1.04);
          visibility: hidden;
          pointer-events: none;
        }
        .leg-orb-a {
          position: fixed;
          width: 340px;
          height: 340px;
          border-radius: 50%;
          top: -80px;
          right: -60px;
          background: radial-gradient(circle, rgba(201, 242, 122, 0.22), transparent 70%);
          filter: blur(28px);
          pointer-events: none;
          animation: legOrbFloat 7s ease-in-out infinite;
        }
        .leg-orb-b {
          position: fixed;
          width: 380px;
          height: 380px;
          border-radius: 50%;
          bottom: -100px;
          left: -70px;
          background: radial-gradient(circle, rgba(56, 189, 248, 0.2), transparent 70%);
          filter: blur(32px);
          pointer-events: none;
          animation: legOrbFloat 8.5s ease-in-out infinite reverse;
        }
        .leg-grid-bg {
          position: fixed;
          inset: 0;
          background-image:
            linear-gradient(to right, rgba(201, 242, 122, 0.05) 1px, transparent 1px),
            linear-gradient(to bottom, rgba(201, 242, 122, 0.05) 1px, transparent 1px);
          background-size: 48px 48px;
          mask-image: radial-gradient(circle at center, black 35%, transparent 88%);
          pointer-events: none;
        }
        .leg-card {
          position: relative;
          z-index: 3;
          width: min(860px, 96vw);
          border-radius: 28px;
          padding: clamp(20px, 4vw, 38px);
          background: linear-gradient(145deg, rgba(24, 27, 22, 0.88), rgba(12, 14, 12, 0.94));
          border: 1px solid rgba(201, 242, 122, 0.34);
          box-shadow:
            0 0 0 1px rgba(213, 197, 164, 0.12),
            0 25px 80px rgba(0, 0, 0, 0.78),
            0 0 48px rgba(201, 242, 122, 0.14);
          backdrop-filter: blur(16px);
          display: grid;
          grid-template-columns: 1.25fr 0.75fr;
          gap: 24px;
          align-items: center;
          animation: legCardIn 0.7s cubic-bezier(.2,.75,.2,1) both;
        }
        .leg-pill {
          display: inline-flex;
          align-items: center;
          gap: 8px;
          padding: 5px 13px;
          border-radius: 999px;
          background: rgba(201, 242, 122, 0.12);
          border: 1px solid rgba(201, 242, 122, 0.35);
          color: #c9f27a;
          font-family: 'DM Mono', monospace;
          font-size: 11px;
          letter-spacing: 0.1em;
          margin-bottom: 12px;
        }
        .leg-pill-dot {
          width: 7px;
          height: 7px;
          border-radius: 50%;
          background: #c9f27a;
          box-shadow: 0 0 10px #c9f27a;
          animation: legPulseDot 1.6s infinite;
        }
        .leg-owner-name {
          margin: 0;
          font-size: clamp(26px, 4.2vw, 44px);
          font-weight: 800;
          line-height: 1.2;
          background: linear-gradient(95deg, #ffffff 0%, #c9f27a 52%, #d5c5a4 100%);
          -webkit-background-clip: text;
          -webkit-text-fill-color: transparent;
        }
        .leg-subtitle {
          margin: 8px 0 16px;
          font-size: clamp(13px, 1.8vw, 16px);
          color: #d5c5a4;
          line-height: 1.6;
        }
        .leg-welcome-box {
          background: rgba(255, 255, 255, 0.03);
          border: 1px solid rgba(238, 234, 224, 0.12);
          border-radius: 16px;
          padding: 12px 14px;
          margin-bottom: 16px;
          font-size: 13.5px;
          color: #eeeae0;
          line-height: 1.65;
        }
        .leg-input-row {
          display: flex;
          gap: 10px;
          flex-wrap: wrap;
          margin-bottom: 16px;
        }
        .leg-name-input {
          flex: 1 1 200px;
          background: rgba(10, 12, 10, 0.85);
          border: 1px solid rgba(201, 242, 122, 0.3);
          color: #eeeae0;
          border-radius: 12px;
          padding: 10px 14px;
          font-size: 13.5px;
          outline: none;
        }
        .leg-name-input:focus {
          border-color: #c9f27a;
          box-shadow: 0 0 0 3px rgba(201, 242, 122, 0.16);
        }
        .leg-cta-row {
          display: flex;
          gap: 12px;
          flex-wrap: wrap;
          align-items: center;
        }
        .leg-enter-btn {
          background: linear-gradient(135deg, #c9f27a 0%, #9be15d 100%);
          color: #0d0f0c;
          border: none;
          border-radius: 14px;
          padding: 12px 24px;
          font-weight: 800;
          font-size: 14px;
          cursor: pointer;
          box-shadow: 0 10px 28px rgba(201, 242, 122, 0.32);
          transition: transform 0.22s ease, box-shadow 0.22s ease;
        }
        .leg-enter-btn:hover {
          transform: translateY(-2px);
          box-shadow: 0 14px 34px rgba(201, 242, 122, 0.45);
        }
        .leg-quick-ai-btn {
          background: rgba(56, 189, 248, 0.12);
          color: #7dd3fc;
          border: 1px solid rgba(56, 189, 248, 0.35);
          border-radius: 14px;
          padding: 11px 16px;
          font-weight: 700;
          font-size: 13px;
          cursor: pointer;
        }
        .leg-char-panel {
          position: relative;
          display: flex;
          flex-direction: column;
          align-items: center;
          justify-content: center;
          min-height: 290px;
          border-radius: 22px;
          padding: 14px;
          background:
            radial-gradient(circle at 50% 35%, rgba(201, 242, 122, 0.22), transparent 62%),
            rgba(10, 12, 10, 0.65);
          border: 1px solid rgba(201, 242, 122, 0.25);
        }
        .leg-char-img {
          width: 185px;
          height: 265px;
          object-fit: contain;
          filter: drop-shadow(0 14px 26px rgba(0, 0, 0, 0.7)) drop-shadow(0 0 16px rgba(201, 242, 122, 0.24));
          animation: legCharFloat 3.2s ease-in-out infinite;
        }
        .leg-char-caption {
          margin-top: 6px;
          font-size: 12px;
          color: #c9f27a;
          font-weight: 600;
          text-align: center;
        }
        @keyframes legCardIn {
          from { opacity: 0; transform: translateY(24px) scale(0.97); }
          to { opacity: 1; transform: translateY(0) scale(1); }
        }
        @keyframes legCharFloat {
          0%, 100% { transform: translateY(0px); }
          50% { transform: translateY(-7px); }
        }
        @keyframes legOrbFloat {
          0%, 100% { transform: translate(0, 0) scale(1); }
          50% { transform: translate(-18px, 16px) scale(1.06); }
        }
        @keyframes legPulseDot {
          0%, 100% { transform: scale(1); opacity: 1; }
          50% { transform: scale(1.35); opacity: 0.65; }
        }
        @media (max-width: 760px) {
          .leg-card {
            grid-template-columns: 1fr;
            text-align: center;
          }
          .leg-cta-row, .leg-input-row {
            justify-content: center;
          }
          .leg-char-panel {
            min-height: 220px;
          }
          .leg-char-img {
            width: 145px;
            height: 205px;
          }
        }
      `;
      document.head.appendChild(entryStyle);

      const gate = document.createElement('div');
      gate.id = 'legendaryEntryGate';
      gate.setAttribute('role', 'dialog');
      gate.setAttribute('aria-modal', 'true');
      gate.setAttribute('aria-label', 'بوابة الدخول الترحيبية لجهاد محمد سنان الوصابي');
      const savedVisitor = localStorage.getItem('jihad-visitor-name') || '';
      gate.innerHTML = `
        <div class="leg-grid-bg"></div>
        <div class="leg-orb-a"></div>
        <div class="leg-orb-b"></div>
        <div class="leg-card">
          <div>
            <div class="leg-pill"><span class="leg-pill-dot"></span><span>LEGENDARY ENTRY · ARCHITECTURAL WORLDS</span></div>
            <h1 class="leg-owner-name">${isEn() ? 'Jihad Mohammed Sinan Al-Wosabi' : 'جهاد محمد سنان الوصابي'}</h1>
            <p class="leg-subtitle">${isEn()
              ? 'Computer Information Systems (CIS) · Systems Architecture, Databases & Interactive Worlds'
              : 'نظم المعلومات الحاسوبية (CIS) · هندسة الأنظمة، قواعد البيانات والعوالم التفاعلية'}</p>
            <div class="leg-welcome-box" id="legWelcomeMsg">
              ${isEn()
                ? 'Welcome! My anime persona welcomes you to Jihad Al-Wosabi\'s world. Enter your name if you like and step right in!'
                : 'أهلاً وسهلاً بك! شخصيتي الأنمي ترحب بك في موقع جهاد محمد سنان الوصابي. اكتب اسمك إن أحببت ثم ادخل إلى التجربة الأسطورية!'}
            </div>
            <div class="leg-input-row">
              <input type="text" class="leg-name-input" id="legVisitorInput" value="${savedVisitor.replace(/"/g, '&quot;')}" placeholder="${isEn() ? 'Your name (optional)...' : 'اكتب اسمك هنا (اختياري)...'}">
            </div>
            <div class="leg-cta-row">
              <button type="button" class="leg-enter-btn" id="legEnterBtn">${isEn() ? 'Enter Legendary World ✦' : 'دخول الموقع الآن ✦'}</button>
              <button type="button" class="leg-quick-ai-btn" id="legAskBtn">${isEn() ? 'Ask Jihad AI' : 'تحدث مع جهاد AI'}</button>
            </div>
          </div>
          <div class="leg-char-panel">
            <img class="leg-char-img" id="legCharImg" src="${MASCOT_SPRITES.wave}" alt="جهاد الوصابي - ترحيب تفاعلي">
            <div class="leg-char-caption" id="legCharCaption">${isEn() ? 'Waving & welcoming you!' : 'يرحّب بك ويفتح لك الأبواب!'}</div>
          </div>
        </div>
      `;
      document.body.appendChild(gate);

      const visitorInput = document.getElementById('legVisitorInput');
      const welcomeMsg = document.getElementById('legWelcomeMsg');
      const charImg = document.getElementById('legCharImg');
      const charCaption = document.getElementById('legCharCaption');

      visitorInput?.addEventListener('input', () => {
        const vName = visitorInput.value.trim();
        if (vName) {
          if (charImg) charImg.src = MASCOT_SPRITES.excited;
          if (charCaption) charCaption.textContent = isEn() ? `Excited to meet you, ${vName}!` : `سعيد جداً بوجودك يا ${vName}!`;
          if (welcomeMsg) welcomeMsg.textContent = isEn()
            ? `Welcome, ${vName}! Jihad Mohammed Sinan Al-Wosabi's interactive portfolio & AI assistant are ready for you.`
            : `أهلاً بك يا ${vName}! موقع جهاد محمد سنان الوصابي ومساعده الذكي بانتظارك.`;
        } else {
          if (charImg) charImg.src = MASCOT_SPRITES.wave;
          if (charCaption) charCaption.textContent = isEn() ? 'Waving & welcoming you!' : 'يرحّب بك ويفتح لك الأبواب!';
        }
      });

      let gateClosed = false;
      const enterSite = (openAiAfter = false) => {
        if (gateClosed) return;
        gateClosed = true;
        const vName = (visitorInput?.value || '').trim();
        if (vName) {
          try { localStorage.setItem('jihad-visitor-name', vName); } catch (_) {}
        }
        gate.classList.add('is-entering');
        setTimeout(() => {
          gate.remove();
          entryStyle.remove();
          const greetText = vName
            ? (isEn() ? `Welcome aboard, ${vName}! Ask me anything!` : `أهلاً بك يا ${vName} في موقع جهاد! اسألني أي سؤال!`)
            : (isEn() ? 'Welcome! Ask me anything about Jihad or any topic!' : 'أهلاً بك! اسألني أي سؤال عن جهاد أو أي موضوع!');
          setMascotMood('excited', greetText, 5000);
          if (openAiAfter) {
            const panel = document.getElementById('aiPanel');
            panel?.classList.add('open');
            document.getElementById('aiQuestion')?.focus();
          }
        }, 720);
      };

      document.getElementById('legEnterBtn')?.addEventListener('click', () => enterSite(false));
      document.getElementById('legAskBtn')?.addEventListener('click', () => enterSite(true));
    }
  } catch (_) {}

  // 0B. Interactive Anime Companion of Jihad Al-Wosabi (#jihadAnimeCompanion)
  try {
    const mascotStyle = document.createElement('style');
    mascotStyle.id = 'jihadMascotStyles';
    mascotStyle.textContent = `
      #jihadAnimeCompanion {
        position: fixed;
        bottom: 84px;
        left: 18px;
        z-index: 9990;
        display: flex;
        flex-direction: column;
        align-items: flex-start;
        gap: 8px;
        user-select: none;
        transition: transform 0.35s cubic-bezier(.2,.75,.2,1);
      }
      html[dir="ltr"] #jihadAnimeCompanion {
        left: auto;
        right: 18px;
        align-items: flex-end;
      }
      .jac-bubble {
        max-width: 245px;
        background: rgba(20, 22, 18, 0.94);
        color: #eeeae0;
        border: 1px solid rgba(201, 242, 122, 0.42);
        border-radius: 16px;
        padding: 9px 13px;
        font-size: 12.5px;
        line-height: 1.5;
        box-shadow: 0 14px 36px rgba(0, 0, 0, 0.6), 0 0 18px rgba(201, 242, 122, 0.12);
        backdrop-filter: blur(10px);
        opacity: 1;
        transform: translateY(0);
        transition: opacity 0.25s ease, transform 0.25s ease;
        cursor: pointer;
      }
      .jac-bubble.is-hidden {
        opacity: 0;
        transform: translateY(6px);
        pointer-events: none;
      }
      .jac-bubble-tag {
        display: block;
        font-family: 'DM Mono', monospace;
        font-size: 10px;
        color: #c9f27a;
        margin-bottom: 3px;
        letter-spacing: 0.06em;
      }
      .jac-stage {
        position: relative;
        width: 112px;
        height: 178px;
        cursor: pointer;
        display: flex;
        align-items: flex-end;
        justify-content: center;
        filter: drop-shadow(0 12px 24px rgba(0, 0, 0, 0.65));
        transition: transform 0.28s cubic-bezier(.2,.75,.2,1);
      }
      .jac-stage:hover {
        transform: translateY(-4px) scale(1.04);
      }
      .jac-aura {
        position: absolute;
        bottom: 6px;
        width: 82px;
        height: 22px;
        border-radius: 50%;
        background: radial-gradient(ellipse at center, rgba(201, 242, 122, 0.5) 0%, transparent 72%);
        animation: jacPulse 2.8s ease-in-out infinite;
        pointer-events: none;
      }
      .jac-avatar {
        width: 108px;
        height: 174px;
        object-fit: contain;
        transform-origin: bottom center;
        animation: jacFloat 3.4s ease-in-out infinite;
        transition: opacity 0.18s ease, transform 0.25s ease;
      }
      .jac-stage[data-mood="excited"] .jac-avatar {
        animation: jacBounce 0.65s ease-in-out 2;
      }
      .jac-stage[data-mood="thinking"] .jac-avatar {
        animation: jacTilt 2.2s ease-in-out infinite;
      }
      .jac-stage[data-mood="wave"] .jac-avatar,
      .jac-stage[data-mood="greet"] .jac-avatar {
        animation: jacWave 1.2s ease-in-out 2;
      }
      .jac-badge {
        position: absolute;
        bottom: 2px;
        background: #141612;
        border: 1px solid rgba(201, 242, 122, 0.45);
        color: #c9f27a;
        font-size: 10.5px;
        font-weight: 600;
        padding: 2px 9px;
        border-radius: 999px;
        white-space: nowrap;
        box-shadow: 0 4px 14px rgba(0,0,0,0.5);
      }
      @keyframes jacFloat {
        0%, 100% { transform: translateY(0px) rotate(0deg); }
        50% { transform: translateY(-5px) rotate(0.6deg); }
      }
      @keyframes jacBounce {
        0%, 100% { transform: translateY(0) scale(1); }
        40% { transform: translateY(-11px) scale(1.04); }
        70% { transform: translateY(-3px) scale(0.99); }
      }
      @keyframes jacTilt {
        0%, 100% { transform: rotate(0deg) translateY(0); }
        50% { transform: rotate(-2.4deg) translateY(-3px); }
      }
      @keyframes jacWave {
        0%, 100% { transform: rotate(0deg); }
        25% { transform: rotate(2.5deg) translateY(-3px); }
        75% { transform: rotate(-2deg); }
      }
      @keyframes jacPulse {
        0%, 100% { transform: scale(0.92); opacity: 0.75; }
        50% { transform: scale(1.12); opacity: 1; }
      }
      @media (max-width: 640px) {
        #jihadAnimeCompanion { bottom: 76px; left: 10px; }
        html[dir="ltr"] #jihadAnimeCompanion { right: 10px; }
        .jac-stage { width: 88px; height: 142px; }
        .jac-avatar { width: 84px; height: 138px; }
        .jac-bubble { max-width: 195px; font-size: 11.5px; padding: 7px 10px; }
      }
    `;
    document.head.appendChild(mascotStyle);

    const wrap = document.createElement('div');
    wrap.id = 'jihadAnimeCompanion';
    wrap.innerHTML = `
      <div class="jac-bubble" id="jacBubble" title="اضغط للتحدث مع جهاد الذكي">
        <span class="jac-bubble-tag">JIHAD AI · ONLINE</span>
        <span id="jacBubbleText">${isEn() ? 'Hi! I am Jihad AI. Ask me anything or tap me to chat!' : 'أهلاً بك! أنا مساعد جهاد الذكي. اضغط عليّ واسألني أي سؤال!'}</span>
      </div>
      <div class="jac-stage" id="jacStage" data-mood="wave" role="button" tabindex="0" aria-label="مساعد جهاد الوصابي التفاعلي">
        <div class="jac-aura"></div>
        <img class="jac-avatar" id="jacAvatarImg" src="${MASCOT_SPRITES.wave}" alt="جهاد الوصابي - المساعد الذكي">
        <span class="jac-badge">✦ ${isEn() ? 'Ask Jihad AI' : 'اسأل جهاد AI'}</span>
      </div>
    `;
    document.body.appendChild(wrap);

    const stage = document.getElementById('jacStage');
    const avatarImg = document.getElementById('jacAvatarImg');
    const bubble = document.getElementById('jacBubble');
    const bubbleText = document.getElementById('jacBubbleText');
    let revertTimer = null;

    setMascotMood = (mood, customMessage = '', durationMs = 4500) => {
      const key = MASCOT_SPRITES[mood] ? mood : 'idle';
      if (stage) stage.dataset.mood = key;
      if (avatarImg && avatarImg.src !== MASCOT_SPRITES[key]) {
        avatarImg.style.opacity = '0.78';
        avatarImg.src = MASCOT_SPRITES[key];
        requestAnimationFrame(() => { avatarImg.style.opacity = '1'; });
      }
      if (customMessage && bubbleText && bubble) {
        bubbleText.textContent = customMessage;
        bubble.classList.remove('is-hidden');
      }
      clearTimeout(revertTimer);
      if (durationMs > 0 && key !== 'idle') {
        revertTimer = setTimeout(() => {
          if (stage) stage.dataset.mood = 'idle';
          if (avatarImg) avatarImg.src = MASCOT_SPRITES.idle;
        }, durationMs);
      }
    };

    const openAssistantWithCompanion = () => {
      const panel = document.getElementById('aiPanel');
      const input = document.getElementById('aiQuestion');
      if (panel && !panel.classList.contains('open')) {
        panel.classList.add('open');
      }
      setMascotMood(
        'excited',
        isEn() ? 'Ready! Ask me anything about the project or any topic!' : 'جاهز! اسألني أي سؤال عن المشروع أو أي موضوع في بالك!',
        4000
      );
      setTimeout(() => input?.focus(), 80);
    };

    stage?.addEventListener('click', openAssistantWithCompanion);
    bubble?.addEventListener('click', openAssistantWithCompanion);
    stage?.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        openAssistantWithCompanion();
      }
    });

    let lastScrollBucket = -1;
    window.addEventListener('scroll', () => {
      const ratio = window.scrollY / Math.max(1, document.documentElement.scrollHeight - window.innerHeight);
      const bucket = Math.min(4, Math.floor(ratio * 5));
      if (bucket !== lastScrollBucket) {
        lastScrollBucket = bucket;
        const reactions = [
          { mood: 'wave', ar: 'مرحباً بك في عوالمي الرقمية المعمارية!', en: 'Welcome to my Architectural Digital Worlds!' },
          { mood: 'thinking', ar: 'هنا أستعرض مهاراتي وأنظمة المعلومات وقواعد البيانات.', en: 'Exploring CIS skills, systems analysis, and databases.' },
          { mood: 'excited', ar: 'تصفّح المشاريع والتفاصيل المعمارية، وأنا جاهز لأي سؤال!', en: 'Check out the projects—ask me anything anytime!' },
          { mood: 'greet', ar: 'رحلتي بين مدن اليمن والسعودية موثقة بالصور والخريطة.', en: 'My journey across Yemen & Saudi Arabia with real photos.' },
          { mood: 'wave', ar: 'يسعدني تواصلك أو حجز موعد أو سؤالي في أي موضوع!', en: 'Feel free to reach out, book a meeting, or ask anything!' }
        ];
        const r = reactions[bucket];
        setMascotMood(r.mood, isEn() ? r.en : r.ar, 3600);
      }
    }, { passive: true });

    const aiHead = document.querySelector('#aiPanel .ai-head');
    if (aiHead && !document.getElementById('aiHeadAvatar')) {
      const mini = document.createElement('img');
      mini.id = 'aiHeadAvatar';
      mini.src = MASCOT_SPRITES.greet;
      mini.alt = 'Jihad AI';
      mini.style.cssText = 'width:34px;height:34px;border-radius:50%;object-fit:cover;object-position:top;border:1.5px solid #c9f27a;background:#141612;margin-inline-end:8px;';
      aiHead.insertBefore(mini, aiHead.firstChild);
    }
  } catch (_) {}

// Update backend service badges across UI
  document.querySelectorAll('[data-backend-badge]').forEach((badge) => {
    badge.dataset.connected = ready ? 'true' : 'false';
    const arText = ready
      ? 'الخدمة الخلفية متصلة (Supabase Ready)'
      : 'وضع العرض المحلي · يتطلب ربط Supabase للتشغيل الفعلي';
    const enText = ready
      ? 'Backend Connected (Supabase Ready)'
      : 'Local Preview Mode · Connect Supabase to enable live delivery';
    badge.dataset.ar = arText;
    badge.dataset.en = enText;
    badge.textContent = dict(arText, enText);
  });

  // 1. Contact Form (#portfolioContactForm)
  const form = document.getElementById('portfolioContactForm');
  const status = document.getElementById('contactFormStatus');
  if (form) {
    setStatus(
      status,
      ready
        ? dict('قناة الإرسال جاهزة ومربوطة بالخادم.', 'Messaging channel is connected and ready.')
        : dict(
            'النموذج جاهز للتحقق محليًا؛ الإرسال الفعلي يتفعّل فور ربط Supabase ونشر وظيفة contact.',
            'Form validates locally; live delivery activates once Supabase and the contact function are configured.'
          ),
      ready ? 'ready' : 'offline'
    );

    form.addEventListener('submit', async (e) => {
      e.preventDefault();
      if (!form.reportValidity()) return;
      const f = new FormData(form);
      // Honeypot anti-spam check
      if (f.get('website')) {
        form.reset();
        return;
      }
      const name = String(f.get('name') || '').trim();
      const email = String(f.get('email') || '').trim();
      const subject = String(f.get('subject') || '').trim();
      const message = String(f.get('message') || '').trim();
      const consent = f.get('consent') === 'on';

      if (!consent || name.length < 2 || subject.length < 2 || message.length < 10) {
        const errMsg = dict(
          'يرجى إكمال الحقول المطلوبة (الرسالة 10 أحرف على الأقل) والموافقة على التواصل.',
          'Please complete all required fields (message at least 10 characters) and confirm consent.'
        );
        setStatus(status, errMsg, 'error');
        showToast(errMsg, 'error');
        return;
      }

      const btn = form.querySelector('button[type="submit"]');
      if (btn) btn.disabled = true;
      setStatus(status, dict('جارٍ إرسال رسالتك بأمان…', 'Sending your message securely…'), 'loading');

      try {
        await invoke(cfg.CONTACT_FUNCTION || 'contact', {
          name,
          email,
          subject,
          message,
          consent
        });
        form.reset();
        const okMsg = dict('تم استلام رسالتك بنجاح. شكرًا لتواصلك.', 'Your message was sent successfully. Thank you.');
        setStatus(status, okMsg, 'success');
        showToast(okMsg, 'success');
      } catch (err) {
        setStatus(status, err.message, 'error');
        showToast(err.message, 'error');
      } finally {
        if (btn) btn.disabled = false;
      }
    });
  }

  // 2. Appointment Booking Form (#appointmentForm)
  const appointmentForm = document.getElementById('appointmentForm');
  const appointmentStatus = document.getElementById('appointmentStatus');
  if (appointmentForm) {
    const dtInput = appointmentForm.querySelector('input[name="requested_at"]');
    if (dtInput) {
      const minDate = new Date(Date.now() + 60 * 60 * 1000);
      dtInput.min = minDate.toISOString().slice(0, 16);
    }
    setStatus(
      appointmentStatus,
      ready
        ? dict('حجز المواعيد مربوط بقاعدة البيانات.', 'Appointment scheduling is connected to the database.')
        : dict(
            'يتطلب حفظ الموعد في قاعدة البيانات ربط Supabase ونشر وظيفة appointment.',
            'Saving appointments to the database requires configuring Supabase and deploying appointment.'
          ),
      ready ? 'ready' : 'offline'
    );

    appointmentForm.addEventListener('submit', async (e) => {
      e.preventDefault();
      if (!appointmentForm.reportValidity()) return;
      const f = new FormData(appointmentForm);
      const rawDate = String(f.get('requested_at') || '');
      const parsed = new Date(rawDate);
      if (Number.isNaN(parsed.getTime()) || parsed.getTime() < Date.now() + 30 * 60 * 1000) {
        const errMsg = dict(
          'يرجى اختيار تاريخ ووقت مستقبلي (بعد 30 دقيقة على الأقل من الآن).',
          'Please select a future date and time (at least 30 minutes from now).'
        );
        setStatus(appointmentStatus, errMsg, 'error');
        showToast(errMsg, 'error');
        return;
      }

      const btn = appointmentForm.querySelector('button[type="submit"]');
      if (btn) btn.disabled = true;
      setStatus(appointmentStatus, dict('جارٍ تسجيل طلب الموعد…', 'Submitting appointment request…'), 'loading');

      try {
        await invoke(cfg.APPOINTMENT_FUNCTION || 'appointment', {
          name: String(f.get('name') || '').trim(),
          email: String(f.get('email') || '').trim(),
          requested_at: parsed.toISOString(),
          timezone: String(f.get('timezone') || Intl.DateTimeFormat().resolvedOptions().timeZone || 'Asia/Aden'),
          purpose: String(f.get('purpose') || '').trim(),
          notes: String(f.get('notes') || '').trim()
        });
        appointmentForm.reset();
        const okMsg = dict(
          'تم استلام طلب الموعد بنجاح، وسيتم التواصل معك لتأكيده.',
          'Appointment request received. We will contact you to confirm.'
        );
        setStatus(appointmentStatus, okMsg, 'success');
        showToast(okMsg, 'success');
      } catch (err) {
        setStatus(appointmentStatus, err.message, 'error');
        showToast(err.message, 'error');
      } finally {
        if (btn) btn.disabled = false;
      }
    });
  }

  // 3. Universal & Personal AI Assistant (#aiPanel, #aiLaunch, #aiForm)
  const aiPanel = document.getElementById('aiPanel');
  const aiLaunch = document.getElementById('aiLaunch');
  const aiClose = document.getElementById('aiClose');
  const aiForm = document.getElementById('aiForm');
  const aiQuestion = document.getElementById('aiQuestion');
  const aiLog = document.getElementById('aiLog');
  const aiHistory = [];

  const addMsg = (text, who) => {
    if (!aiLog) return;
    const d = document.createElement('div');
    d.className = 'ai-msg ' + who;
    d.style.whiteSpace = 'pre-line';
    d.textContent = text;
    aiLog.appendChild(d);
    aiLog.scrollTop = aiLog.scrollHeight;
  };

  const safeEvalMath = (expr) => {
    const cleaned = expr
      .replace(/×/g, '*')
      .replace(/÷/g, '/')
      .replace(/[^0-9+\-*/().%^\s]/g, '')
      .replace(/\^/g, '**')
      .trim();
    if (!cleaned || !/[0-9]/.test(cleaned)) return null;
    if (/[a-zA-Z_$]/.test(cleaned)) return null;
    try {
      const fn = new Function('return (' + cleaned + ');');
      const val = fn();
      if (typeof val === 'number' && Number.isFinite(val)) {
        return Number.isInteger(val) ? String(val) : String(Math.round(val * 1e6) / 1e6);
      }
    } catch (_) {}
    return null;
  };

  const fetchWithTimeout = async (url, ms = 5000) => {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), ms);
    try {
      return await fetch(url, { signal: controller.signal });
    } finally {
      clearTimeout(timer);
    }
  };

  const universalLocalAnswer = async (q) => {
    const raw = String(q || '').trim();
    const s = raw.toLowerCase();
    const en = isEn() || (!/[\u0600-\u06FF]/.test(raw) && /[a-zA-Z]{3,}/.test(raw));

    if (/^(السلام عليكم|مرحبا|أهلا|اهلا|هلا|صباح الخير|مساء الخير|hi|hello|hey|good morning|good evening)[!؟?.\s]*$/i.test(raw)) {
      return en
        ? 'Hello! I am Jihad Al-Wosabi\'s interactive AI assistant. Ask me anything—about Jihad\'s CIS studies, projects, databases, programming, math, science, or any general topic!'
        : 'وعليكم السلام وأهلاً بك! أنا مساعد جهاد الوصابي الذكي. اسألني أي سؤال يخطر ببالك سواء عن تخصص جهاد ومشاريعه أو في البرمجة وقواعد البيانات والعلوم والحساب وأي مجال عام!';
    }

    const mathMatch = raw.match(/(?:احسب|حساب|كم يساوي|calculate|calc|what is)?\s*([0-9]+(?:\.[0-9]+)?(?:\s*[+\-*/×÷^%]\s*[0-9]+(?:\.[0-9]+)?)+)/i);
    if (mathMatch) {
      const res = safeEvalMath(mathMatch[1]);
      if (res !== null) {
        return en
          ? `Calculation result for (${mathMatch[1].trim()}) = ${res}`
          : `ناتج العملية الحسابية (${mathMatch[1].trim()}) يساوي: ${res}`;
      }
    }

    if (/مشروع|مشاريع|فندق|مستشفى|كافيه|قاعدة|قواعد|project|hotel|hospital|cafe|database|erd|sql|oracle/.test(s)) {
      return en
        ? 'Jihad Al-Wosabi showcases architectural & CIS systems including: Smart Hotel Management System (Oracle/SQL & desktop/web workflows), Integrated Hospital System, Modern Café POS System, and Relational ERD/Database Models.'
        : 'تشمل مشاريع جهاد الوصابي في نظم المعلومات وقواعد البيانات: نظام إدارة الفنادق الذكي (المرتبط بقواعد بيانات Oracle / SQL)، نظام المستشفى المتكامل، نظام الكافيه الحديث، ونماذج قواعد البيانات العلائقية (ERD / SQL) وتصميم الواجهات.';
    }
    if (/شهادة|شهادات|تعليم|جامعة|دراسة|تخصص|cis|معلومات|certificate|education|university|degree|jihad|جهاد|الوصابي/.test(s)) {
      return en
        ? 'Jihad Mohammed Sinan Al-Wosabi studies Computer Information Systems (CIS) at the College of Computer, University of Saba Region (Marib, Yemen), focusing on systems analysis, Oracle/SQL databases, information security, algorithms, and web/desktop development. Certificates: ICDL, Intermediate English Diploma, and Electrical Studies & Practice Diploma.'
        : 'جهاد محمد سنان الوصابي طالب في تخصص نظم المعلومات الحاسوبية (CIS) بكلية الحاسوب في جامعة إقليم سبأ (مأرب، اليمن)، ويهتم بتحليل الأنظمة، قواعد البيانات (Oracle / SQL)، أمن المعلومات، الخوارزميات، وتطوير المواقع والتطبيقات. الشهادات المدرجة: ICDL، دبلوم اللغة الإنجليزية (متوسط)، ودبلوم دراسة وتطبيق الكهرباء.';
    }
    if (/تواصل|بريد|هاتف|تيليجرام|ايميل|رقم|contact|email|phone|telegram|reach/.test(s)) {
      return en
        ? 'Contact Jihad Al-Wosabi:\n• Email: jihad7840296682005@gmail.com\n• Phone: +967 784 029 668\n• Telegram: https://t.me/ji7840'
        : 'بيانات التواصل المباشر مع جهاد الوصابي:\n• البريد الإلكتروني: jihad7840296682005@gmail.com\n• الهاتف: +967 784 029 668\n• تيليجرام: https://t.me/ji7840';
    }
    if (/مدينة|مدن|رحلة|سفر|اليمن|السعودية|مأرب|ذمار|صعدة|تريم|حضرموت|place|city|cities|journey|yemen|saudi|marib|tarim/.test(s)) {
      return en
        ? 'The Journey world covers 13 regions in Yemen (Sanaa, Saada, Amran, Al Jawf, Marib, Dhamar, Mukalla, Seiyun, Tarim, Wadi Dawan, Shibam Hadramout, Shabwa, Howf - Al Mahrah) and 7 cities in Saudi Arabia (Makkah, Madinah, Jeddah, Riyadh, Jazan, Abha, Taif).'
        : 'يغطي عالم الرحلة 13 منطقة في اليمن (صنعاء، صعدة، عمران، الجوف، مأرب، ذمار، المكلا، سيئون، تريم، وادي دوعن، شبام حضرموت، شبوة، والمهرة – حوف) و7 مدن في السعودية (مكة، المدينة المنورة، جدة، الرياض، جازان، أبها، والطائف).';
    }

    const cleanTopic = raw
      .replace(/^(ما هو|ما هي|من هو|من هي|من يكون|عرف|تعريف|اشرح|شرح|كيف يعمل|كيف|لماذا|متى|أين|نبذة عن|معلومات عن|what is|what are|who is|who was|explain|how does|how to|why is|define|tell me about)\s+/i, '')
      .replace(/[؟?.,!]+$/g, '')
      .trim();

    const langOrder = /[\u0600-\u06FF]/.test(raw) ? ['ar', 'en'] : ['en', 'ar'];

    for (const langCode of langOrder) {
      for (const term of [cleanTopic, raw].filter(Boolean)) {
        try {
          const wikiUrl = `https://${langCode}.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(term)}`;
          const r = await fetchWithTimeout(wikiUrl, 4500);
          if (r.ok) {
            const data = await r.json();
            if (data && data.extract && data.type !== 'disambiguation') {
              return data.extract;
            }
          }
        } catch (_) {}
      }
    }

    for (const langCode of langOrder) {
      try {
        const srchUrl = `https://${langCode}.wikipedia.org/w/api.php?action=query&list=search&srsearch=${encodeURIComponent(cleanTopic || raw)}&srlimit=3&format=json&origin=*`;
        const r = await fetchWithTimeout(srchUrl, 4500);
        if (r.ok) {
          const d = await r.json();
          const hits = d?.query?.search || [];
          for (const hit of hits) {
            if (!hit?.title) continue;
            const sumRes = await fetchWithTimeout(`https://${langCode}.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(hit.title)}`, 4500);
            if (sumRes.ok) {
              const sumData = await sumRes.json();
              if (sumData?.extract && sumData.type !== 'disambiguation') {
                return `📌 ${sumData.title}:\n${sumData.extract}`;
              }
            }
          }
        }
      } catch (_) {}
    }

    try {
      const ddgUrl = `https://api.duckduckgo.com/?q=${encodeURIComponent(cleanTopic || raw)}&format=json&no_html=1&skip_disambig=1`;
      const ddgRes = await fetchWithTimeout(ddgUrl, 4000);
      if (ddgRes.ok) {
        const ddg = await ddgRes.json();
        const ans = ddg.AbstractText || ddg.Answer || ddg.Definition;
        if (ans && String(ans).trim().length > 10) {
          return String(ans).trim();
        }
      }
    } catch (_) {}

    return en
      ? `Regarding "${raw}": I searched my knowledge sources for this query. Try rephrasing with key terms, or connect OPENAI_API_KEY in Supabase Edge Functions for full generative AI reasoning.`
      : `بخصوص سؤالك ("${raw}"): حاولت البحث في مصادر المعرفة المتاحة ولم أجد ملخصاً مباشراً بهذه الصياغة. جرّب كتابة الكلمة المفتاحية الأساسية (مثل اسم تقنية أو عالم أو مفهوم) أو اربط مفتاح OPENAI_API_KEY في Supabase لتفعيل الإجابة التحليلية الكاملة.`;
  };

  aiLaunch?.addEventListener('click', () => {
    if (!aiPanel) return;
    aiPanel.classList.toggle('open');
    if (aiPanel.classList.contains('open')) {
      aiQuestion?.focus();
      setMascotMood('excited', isEn() ? 'I am listening! Type your question.' : 'أنا أستمع لك! اكتب سؤالك الآن.', 3000);
    }
  });
  aiClose?.addEventListener('click', () => {
    aiPanel?.classList.remove('open');
    setMascotMood('wave', isEn() ? 'I am right here whenever you need help!' : 'أنا موجود هنا متى ما احتجت مساعدة!', 3000);
  });

  document.querySelectorAll('[data-ai-prompt]').forEach((chip) => {
    chip.addEventListener('click', () => {
      if (!aiQuestion || !aiForm) return;
      aiQuestion.value = isEn() ? chip.dataset.en || chip.textContent : chip.dataset.ar || chip.textContent;
      aiForm.dispatchEvent(new Event('submit', { cancelable: true }));
    });
  });

  aiForm?.addEventListener('submit', async (e) => {
    e.preventDefault();
    if (!aiQuestion) return;
    const q = aiQuestion.value.trim();
    if (!q) return;
    addMsg(q, 'user');
    aiHistory.push({ role: 'user', content: q });
    aiQuestion.value = '';
    aiQuestion.disabled = true;

    setMascotMood('thinking', isEn() ? 'Thinking about your question...' : 'أفكّر في إجابة سؤالك الآن...', 0);

    try {
      if (ready) {
        const result = await invoke(cfg.ASSISTANT_FUNCTION || 'assistant', {
          question: q,
          history: aiHistory.slice(-8),
          language: isEn() ? 'en' : 'ar',
          allowGeneralQuestions: true
        });
        const reply = result.answer || (await universalLocalAnswer(q));
        addMsg(reply, 'bot');
        aiHistory.push({ role: 'assistant', content: reply });
      } else {
        const reply = await universalLocalAnswer(q);
        addMsg(reply, 'bot');
        aiHistory.push({ role: 'assistant', content: reply });
      }
      setMascotMood('excited', isEn() ? 'Done! Ask me another question!' : 'تفضّل الإجابة! اسألني سؤالاً آخر إذا أحببت.', 4200);
    } catch (err) {
      const fallbackReply = await universalLocalAnswer(q);
      addMsg(fallbackReply, 'bot');
      aiHistory.push({ role: 'assistant', content: fallbackReply });
      setMascotMood('excited', isEn() ? 'Here is what I found!' : 'تفضّل ما وجدته لك!', 4200);
    } finally {
      aiQuestion.disabled = false;
      aiQuestion.focus();
    }
  });

  // 4. Canonical QR Code (never points to fake example.com when hosted)
  document.querySelectorAll('.qr-panel img, [data-qr-img]').forEach((qr) => {
    const configuredUrl =
      cfg && cfg.SITE_URL && !String(cfg.SITE_URL).includes('YOUR_') ? cfg.SITE_URL : null;
    const targetUrl =
      location.protocol === 'http:' || location.protocol === 'https:'
        ? location.href.split('#')[0]
        : configuredUrl;
    if (targetUrl) {
      qr.src =
        'https://api.qrserver.com/v1/create-qr-code/?size=220x220&data=' +
        encodeURIComponent(targetUrl);
    }
  });

  // 5. Persist language and last visited world cleanly
  try {
    const langBtn = document.getElementById('langBtn');
    const syncLang = () => {
      localStorage.setItem('jihad-language', document.documentElement.lang || 'ar');
    };
    langBtn?.addEventListener('click', () => setTimeout(syncLang, 25));

    const savedLang = localStorage.getItem('jihad-language');
    if ((savedLang === 'en' || savedLang === 'ar') && savedLang !== document.documentElement.lang) {
      if (typeof window.setLang === 'function') {
        window.setLang(savedLang);
      } else {
        langBtn?.click();
      }
    }

    const lastView = localStorage.getItem('jihad-last-view');
    if (!location.hash && lastView) {
      const dockBtn = document.querySelector('#viewDock [data-view="' + CSS.escape(lastView) + '"]');
      if (dockBtn) setTimeout(() => dockBtn.click(), 10);
    }
    document.querySelectorAll('#viewDock [data-view]').forEach((b) => {
      b.addEventListener('click', () => {
        try {
          localStorage.setItem('jihad-last-view', b.dataset.view);
        } catch (_) {}
      });
    });
  } catch (_) {}

  // 6. Register PWA Service Worker over HTTP/HTTPS
  if ('serviceWorker' in navigator && (location.protocol === 'https:' || location.hostname === 'localhost' || location.hostname === '127.0.0.1')) {
    window.addEventListener('load', () => {
      navigator.serviceWorker.register('/sw.js').catch(() => {});
    });
  }

  // 7. Visitor & Recent Viewers Telemetry (Private to Owner in /admin/)
  try {
    let vid = localStorage.getItem('jihad-anon-visitor-id');
    if (!vid) {
      vid = 'v-' + Math.random().toString(36).slice(2, 10) + '-' + Date.now().toString(36);
      localStorage.setItem('jihad-anon-visitor-id', vid);
    }
    const shortCode = vid.replace(/[^a-zA-Z0-9]/g, '').slice(-6).toUpperCase();
    const visitPayload = {
      visitor_id: vid,
      visitor_label: 'زائر #' + shortCode,
      page_path: location.pathname || '/',
      referrer: document.referrer || '',
      language: document.documentElement.lang || 'ar',
      timezone: Intl.DateTimeFormat().resolvedOptions().timeZone || 'Asia/Aden',
      screen: (window.screen && window.screen.width ? window.screen.width + 'x' + window.screen.height : ''),
      visited_at: new Date().toISOString(),
    };

    // Store in local owner preview buffer so owner can inspect recent activity locally before/alongside Supabase
    const localLog = JSON.parse(localStorage.getItem('jihad-owner-recent-visits') || '[]');
    localLog.unshift(visitPayload);
    localStorage.setItem('jihad-owner-recent-visits', JSON.stringify(localLog.slice(0, 60)));

    if (ready && (location.protocol === 'http:' || location.protocol === 'https:')) {
      invoke(cfg.TRACK_VISIT_FUNCTION || 'track-visit', visitPayload).catch(() => {});
    }
  } catch (_) {}

})();
